mapper.sql:
SELECT
WHERE pay01_company_id = #{companyId} AND emp01_person_id = #{personId}
AND pay01_start_date IN ( SELECT MAX(a.pay01_start_date) FROM pay01_annual a LEFT OUTER JOIN apr01_appr ON apr01_appr_id = a.pay01_appr_id WHERE a.pay01_person_id = emp01_person_id AND a.pay01_start_date <= f_today()
AND COALESCE(apr01_status_cd,'X') = '30' /*(30:완료)*/
)
AND TO_CHAR(pay01_start_date,'yyyy') LIKE #{yearStr}
AND COALESCE(apr01_status_cd, '99') = '30'
AND pay01_person_id NOT IN ( SELECT c.emp03_person_id FROM emp03_trans c WHERE pay01_person_id = c.emp03_person_id AND c.emp03_trans_cd = '900' )
AND COALESCE(apr01_status_cd,'X') = '30' /*(30:완료)*/
ORDER BY pay01_start_date

